  "config": { "version": "1.48.0" },
  "suites": [
    {
      "title": "auth.spec.js",
      "file": "tests/auth.spec.js",
      "specs": [
        {
          "title": "signs in with valid credentials",
          "ok": true,
          "line": 8,
